const body = $input.first().json.body ?? $input.first().json;
const leadId = String(body.lead_id ?? '').trim();
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRe.test(leadId)) {
  return [[], [{ json: { success: false, reason: 'INVALID_LEAD_ID', message: 'lead_id must be a valid UUID.' } }]];
}
return [[{ json: { lead_id: leadId } }], []];

const items = $input.all();
const requestedId = $('VALIDATE - Research Input').first().json.lead_id;
if (items.length === 0) {
  return [[{ json: { success: false, lead_id: requestedId, reason: 'NOT_FOUND', message: 'No lead exists for the provided lead_id.' } }], [], [], []];
}
const lead = items[0].json;
const state = String(lead.research_status || 'NOT_STARTED');
if (state === 'COMPLETED') {
  return [[], [{ json: { success: true, status: 'ALREADY_COMPLETED', research_status: 'COMPLETED', lead_id: lead.id, business_name: lead.business_name, message: 'Research already exists for this lead.' } }], [], []];
}
if (state === 'IN_PROGRESS') {
  var startedAt = lead.research_started_at ? Date.parse(lead.research_started_at) : NaN;
  var STALE_MS = 30 * 60 * 1000;
  if (!isNaN(startedAt) && Date.now() - startedAt > STALE_MS) {
    return [[], [], [], [{ json: { id: lead.id, business_name: lead.business_name, website: lead.website, research_status: lead.research_status, recovered_stale: true } }]];
  }
  return [[], [], [{ json: { success: false, status: 'ALREADY_RUNNING', research_status: 'IN_PROGRESS', lead_id: lead.id, business_name: lead.business_name, message: 'Research is already running for this lead.' } }], []];
}
return [[], [], [], [{ json: lead }]];

const lead = $('LOOKUP - Lead by ID').first().json;
const website = String(lead.website || '').trim();
if (!website) {
  return [[], [{ json: { success: false, lead_id: lead.id, business_name: lead.business_name, failure: { status: 'FAILED', reason: 'NO_WEBSITE', message: 'No company website is available for this lead.' } } }]];
}
if (!/^https?:\/\//i.test(website)) {
  return [[], [{ json: { success: false, lead_id: lead.id, business_name: lead.business_name, failure: { status: 'FAILED', reason: 'INVALID_URL', message: 'The stored website URL is not a valid http(s) URL.' } } }]];
}
return [[{ json: lead }], []];

const lead = $('LOOKUP - Lead by ID').first().json;
const raw = $input.first().json;
const msg = String((raw && (raw.message || (raw.error && raw.error.message))) || 'Website request failed').slice(0, 300);
let reason = 'HTTP_ERROR';
if (/timeout|timed out|ETIMEDOUT/i.test(msg)) {
  reason = 'TIMEOUT';
} else if (/ENOTFOUND|EAI_AGAIN|ECONNREFUSED|ENETUNREACH|DNS|getaddrinfo/i.test(msg)) {
  reason = 'WEBSITE_UNAVAILABLE';
}
return [{ json: { success: false, lead_id: lead.id, business_name: lead.business_name, failure: { status: 'FAILED', reason: reason, message: msg } } }];

function clean(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }
const lead = $('LOOKUP - Lead by ID').first().json;
const html = String($input.first().json.data || '').slice(0, 500000);
const stripped = html.replace(/<(script|style|noscript|template|svg|canvas|iframe)[\s\S]*?<\/\1\s*>/gi, ' ');
const titleMatch = stripped.match(/<title[^>]*>([\s\S]*?)<\/title\s*>/i);
const title = clean(titleMatch ? titleMatch[1] : '');
let metaDescription = '';
const metaMatch = stripped.match(/<meta[^>]+(?:name|property)\s*=\s*["']description["'][^>]*>/i);
if (metaMatch) {
  const contentMatch = metaMatch[0].match(/content\s*=\s*["']([^"']*)["']/i);
  if (contentMatch) { metaDescription = clean(contentMatch[1]); }
}
const headings = [];
const headingRe = /<(h1|h2|h3)[^>]*>([\s\S]*?)<\/\1\s*>/gi;
let hm;
while ((hm = headingRe.exec(stripped)) !== null && headings.length < 30) {
  const text = clean(hm[2].replace(/<[^>]+>/g, ' '));
  if (text) { headings.push(text); }
}
const paragraphs = [];
const paraRe = /<p[^>]*>([\s\S]*?)<\/p\s*>/gi;
let pm;
while ((pm = paraRe.exec(stripped)) !== null && paragraphs.length < 40) {
  const text = clean(pm[1].replace(/<[^>]+>/g, ' '));
  if (text.length >= 20) { paragraphs.push(text); }
}
const links = [];
const linkRe = /<a[^>]+href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a\s*>/gi;
let lm;
while ((lm = linkRe.exec(stripped)) !== null && links.length < 50) {
  const text = clean(lm[2].replace(/<[^>]+>/g, ' '));
  const href = lm[1].trim();
  if (text && text.length <= 120 && href) { links.push({ text: text, href: href }); }
}
if (!title && headings.length === 0 && paragraphs.length === 0) {
  return [[], [{ json: { success: false, lead_id: lead.id, business_name: lead.business_name, failure: { status: 'FAILED', reason: 'EMPTY_CONTENT', message: 'The website returned no meaningful text content.' } } }]];
}
const extraction = {
  status: 'FETCHED',
  website: lead.website,
  title: title,
  meta_description: metaDescription,
  headings: headings,
  paragraphs: paragraphs,
  links: links,
  fetched_at: new Date().toISOString(),
  extraction_version: '1'
};
return [[{ json: { lead_id: lead.id, business_name: lead.business_name, website: lead.website, extraction: extraction } }], []];
